mapper.insert:
INSERT INTO notification_history (
    user_id, notification_type, title, body, deep_link, dedupe_key
) VALUES (
    #{userId}, #{notificationType}, #{title}, #{body}, #{deepLink}, #{dedupeKey}
)
ON DUPLICATE KEY UPDATE
    notification_id = LAST_INSERT_ID(notification_id)

mapper.sql:
SELECT CONCAT('N', notification.notification_id) AS notification_key, notification.notification_type, notification.title, notification.body, notification.deep_link, notification.is_read AS `read`, notification.created_at FROM notification_history notification WHERE notification.user_id = #{userId}
UNION ALL
SELECT CONCAT('C', campaign.campaign_id) AS notification_key, campaign.notification_type, campaign.title, campaign.body, campaign.deep_link, receipt.user_id IS NOT NULL AS `read`, campaign.created_at FROM notification_campaign campaign LEFT JOIN notification_campaign_receipt receipt ON receipt.campaign_id = campaign.campaign_id AND receipt.user_id = #{userId} WHERE campaign.visible_from <= #{now} AND (campaign.visible_until IS NULL OR campaign.visible_until >= #{now})

mapper.select:
SELECT notification_key, notification_type, title, body, deep_link, `read`, created_at
FROM (

) feed
ORDER BY created_at DESC, notification_key DESC
LIMIT #{offset}, #{size}

mapper.update:
UPDATE notification_history
SET is_read = TRUE,
    read_at = COALESCE(read_at, #{readAt})
WHERE notification_id = #{notificationId}
  AND user_id = #{userId}

mapper.insert:
INSERT INTO notification_campaign_receipt (campaign_id, user_id, read_at)
SELECT campaign_id, #{userId}, #{readAt}
FROM notification_campaign
WHERE campaign_id = #{campaignId}
  AND visible_from <= #{readAt}
  AND (visible_until IS NULL OR visible_until >= #{readAt})
ON DUPLICATE KEY UPDATE read_at = VALUES(read_at)

INSERT IGNORE INTO notification_campaign_receipt (campaign_id, user_id, read_at)
SELECT campaign_id, #{userId}, #{readAt}
FROM notification_campaign
WHERE visible_from <= #{now}
  AND (visible_until IS NULL OR visible_until >= #{now})

mapper.update:
UPDATE notification_history
SET push_status = 'PROCESSING',
    push_attempts = push_attempts + 1
WHERE notification_id = #{notificationId}
  AND push_status IN ('PENDING', 'PROCESSING')
  AND push_attempts = #{expectedAttempts}

UPDATE notification_campaign
SET push_status = 'PROCESSING',
    push_attempts = push_attempts + 1
WHERE campaign_id = #{campaignId}
  AND push_status IN ('PENDING', 'PROCESSING')
  AND push_attempts = #{expectedAttempts}

UPDATE notification_history
SET push_status = #{status}, sent_at = #{sentAt}
WHERE notification_id = #{notificationId}

UPDATE notification_campaign
SET push_status = #{status}, sent_at = #{sentAt}
WHERE campaign_id = #{campaignId}

UPDATE notification_history
SET push_status = 'FAILED'
WHERE notification_id = #{notificationId}

UPDATE notification_campaign
SET push_status = 'FAILED'
WHERE campaign_id = #{campaignId}
